\begin{align*}
1 - \tan^2 x &= \frac{\cos^2 x}{\sin^2 x}, \text{ and } \frac{\cos^2 x}{\sin^2 x} &= \frac{1}{\csc^2 x - 1}, \text{ and similarly } 1 - \cot^2 x = \frac{1}{\tan^2 x} - 1 = \frac{1}{\sec^2 x - 1}.
\end{align*}
Hence,
\begin{align*}
\frac{1}{1 - \tan^2 x} + \frac{1}{1 - \cot^2 x} &= (\sin^2 x + \cos^2 x)(\csc^2 x - 1 + \tan^2 x + \sec^2 x - 1) \\
&= (\sec^2 x + \csc^2 x - 2)(\sec^2 x + \csc^2 x - 2) \\
&= (\sec^2 x + \csc^2 x - 2)^2.
\end{align*}
